import{c as t,Q as e,j as s,m as l}from"./chunks/framework.DOi4mjdC.js";const m=JSON.parse('{"title":"SetWorkspace","description":"","frontmatter":{},"headers":[{"level":1,"title":"SetWorkspace","slug":"setworkspace"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/高阶API/矩阵计算/Matmul-Kernel侧接口/SetWorkspace.md","filePath":"api/SIMD-API/高阶API/矩阵计算/Matmul-Kernel侧接口/SetWorkspace.md"}'),n={name:"api/SIMD-API/高阶API/矩阵计算/Matmul-Kernel侧接口/SetWorkspace.md"};function r(i,a,d,p,o,c){return e(),s("div",null,[...a[0]||(a[0]=[l(`<h1 id="setworkspace" tabindex="-1">SetWorkspace <a class="header-anchor" href="#setworkspace" aria-label="Permalink to &quot;SetWorkspace&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>√</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>√</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>x</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>x</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr><tr><td>Kirin X90</td><td>√</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p><a href="./Iterate.html">Iterate</a>计算的<a href="./GetTensorC.html#li17508136205415">异步场景</a>，调用本接口申请一块临时空间来缓存计算结果，然后调用<a href="./GetTensorC.html">GetTensorC</a>时会在该临时空间中获取C的矩阵分片。</p><p><a href="./IterateNBatch.html">IterateNBatch</a>计算时，调用本接口申请一块临时空间来缓存计算结果，然后根据<a href="./IterateNBatch.html#table8746171282418">同步或异步场景</a>进行其它接口的调用。</p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><p>建议用户使用GlobalTensor类型传入：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;class T&gt; __aicore__ inline void SetWorkspace(GlobalTensor&lt;T&gt;&amp; addr)</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;class T&gt; __aicore__ inline void SetWorkspace(__gm__ const T* addr, int size)</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>addr</td><td>输入</td><td>用户传入的GM上的workspace空间，GlobalTensor类型。</td></tr><tr><td>addr</td><td>输入</td><td>用户传入的GM上的workspace空间，GM地址类型。</td></tr><tr><td>size</td><td>输入</td><td>传入GM地址时，需要配合传入元素个数。</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><p>当使能MixDualMaster（双主模式）场景时，即模板参数<a href="./MatmulConfig.html#p9218181073719">enableMixDualMaster</a>设置为true，不支持使用该接口。</p><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>REGIST_MATMUL_OBJ(&amp;pipe, GetSysWorkSpacePtr(), mm, &amp;tiling);</span></span>
<span class="line"><span>mm.SetWorkspace(workspaceGM);    //设置异步时使用的临时空间</span></span>
<span class="line"><span>mm.SetTensorA(gm_a);</span></span>
<span class="line"><span>mm.SetTensorB(gm_b);</span></span>
<span class="line"><span>if (tiling.isBias) {</span></span>
<span class="line"><span>    mm.SetBias(biasGlobal);</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>mm.template Iterate&lt;false&gt;();</span></span>
<span class="line"><span>for (int i = 0; i &lt; singleCoreM/baseM * singleCoreN/baseN; ++i) {</span></span>
<span class="line"><span>    mm.template GetTensorC&lt;false&gt;(ub_c);</span></span>
<span class="line"><span>}</span></span></code></pre></div>`,18)])])}const b=t(n,[["render",r]]);export{m as __pageData,b as default};
